import Link from "next/link";
import { notFound } from "next/navigation";
import BackToSelectButton from "../../_components/BackToSelectButton";
import { getAllPostMeta, getPost } from "../../../../lib/posts";

export const dynamic = "force-static";

export function generateStaticParams() {
  return getAllPostMeta("lab").map((p) => ({ slug: p.slug }));
}

export default function LabDetailPage({ params }: { params: { slug: string } }) {
  let post;
  try {
    post = getPost("lab", params.slug);
  } catch {
    notFound();
  }

  return (
    <main className="fixed inset-0 bg-black overflow-hidden">
      <div
        className="absolute inset-0 bg-center bg-no-repeat bg-contain"
        style={{ backgroundImage: "url(/images/contents_bg.jpg)" }}
      />

      <div className="relative z-10 h-full max-w-4xl mx-auto px-6 py-10 text-white">
        {/* 헤더 */}
        <div className="flex items-start justify-between">
          <div>
            <div className="text-xs tracking-[0.22em] text-white/70">CATEGORY</div>
            <h1 className="text-2xl mt-1">AI LAB</h1>

            <div className="mt-4 flex gap-2 text-sm">
              <Link
                href="/ai"
                className="cursor-pointer px-3 py-1.5 rounded-full border border-white/15 bg-black/25 hover:bg-black/35 transition"
              >
                WORK
              </Link>
              <Link
                href="/ai/lab"
                className="cursor-pointer px-3 py-1.5 rounded-full border border-white/20 bg-white/10 hover:bg-white/15 transition"
              >
                LAB
              </Link>
              <Link
                href="/ai/article"
                className="cursor-pointer px-3 py-1.5 rounded-full border border-white/15 bg-black/25 hover:bg-black/35 transition"
              >
                ARTICLE
              </Link>
            </div>
          </div>

          <BackToSelectButton />
        </div>

        {/* 본문 */}
        <div className="mt-8 h-[calc(100%-8.5rem)] overflow-auto pr-1">
          <div className="rounded-2xl border border-white/15 bg-black/25 backdrop-blur-md p-6">
            <div className="text-sm text-white/60">{post.date || ""}</div>
            <div className="mt-2 text-xl">{post.title}</div>
            {post.summary && <div className="mt-3 text-sm text-white/70">{post.summary}</div>}

            <div className="mt-6 border-t border-white/10 pt-6">
              <article
                className="prose prose-invert max-w-none prose-p:leading-relaxed prose-a:underline prose-a:text-white"
                // NOTE: lib/posts.ts의 mdToHtmlLite는 HTML escape 후 변환하므로 기본적으로 안전함
                dangerouslySetInnerHTML={{ __html: post.html }}
              />
            </div>

            <div className="mt-8 flex justify-between text-sm">
              <Link
                href="/ai/lab"
                className="cursor-pointer px-4 py-2 rounded-full border border-white/15 bg-black/20 hover:bg-black/35 transition"
              >
                목록으로
              </Link>
            </div>
          </div>

          <div className="h-10" />
        </div>
      </div>
    </main>
  );
}
